from zipfile import ZipFile
from xml.etree import ElementTree as ET
p='/home/user/workspace/out_a/Finance_Close.pptx'
z=ZipFile(p); print(z.namelist())
for i in range(1,5):
 d=ET.fromstring(z.read(f'ppt/slides/slide{i}.xml'))
 print('\n---slide',i)
 for el in d.iter():
  if el.tag.endswith('}sp'):
   name=''; texts=[]
   for c in el:
    if c.tag.endswith('}nvSpPr'):
     for n in c.iter():
      if n.tag.endswith('}cNvPr'): name=n.attrib.get('name','')
    if c.tag.endswith('}txBody'):
     for t in c.iter():
      if t.tag.endswith('}t') and t.text: texts.append(t.text)
   print(name,repr(''.join(texts)))
